  ], { x: 7.65, y: cbY + 1.95, w: 1.9, h: 1.8, valign: "top", margin: 0 });

  s.addText("Source: Our World in Data", { x: 0.5, y: 5.2, w: 4, h: 0.3, fontSize: 9, fontFace: BF, color: C.muted, margin: 0 });

  // ══════════════════════════════════════════════════════
  // SLIDE 3 — US DISEASE ELIMINATION TABLE
  // ══════════════════════════════════════════════════════
  s = pres.addSlide();
