, h: 0.55, fontSize: 18, fontFace: HF, color: C.dark, bold: true, margin: 0 });\n\n  // Timeline line\n  s.addShape(pres.shapes.LINE, { x: 0.8, y: 2.5, w: 8.4, h: 0, line: { color: C.teal, width: 3 } });\n\n  // Milestone events\n  const tlEvents = [\n    { year: \"1796\", desc: \"Edward Jenner creates first vaccine using cowpox to trigger immunity\", x: 0.8, above: true },\n    { year: \"1959\", desc: \"WHO passes resolution to eradicate smallpox\", x: 2.9, above: false },\n    { year: \"1967\", desc: \"Intensified eradication campaign launched\", x: 5.0, above: true },\n    { year: \"1977\", desc: \"Last natural case occurs in Somalia\", x: 7.1, above: false },\n    { year: \"1980\", desc: \"Smallpox declared eradicated worldwide\", x: 9.2, above: true },\n  ];\n\n  tlEvents.forEach((e) => {\n    // Circle marker on line\n    s.addShape(pres.shapes.OVAL, { x: e.x - 0.12, y: 2.38, w: 0.24, h: 0.24, fill: { color: C.teal } });\n    // Year\n    const yearY = e.above ? 1.6 : 2.8;\n    s.addText(e.year, { x: e.x - 0.5, y: yearY, w: 1.0, h: 0.35, fontSize: 14, fontFace: BF, color: C.teal, bold: true, align: \"center\", valign: \"middle\", margin: 0 });\n    // Description\n    const descY = e.above ? 1.95 : 3.15;\n    s.addText(e.desc, { x: e.x - 0.6, y: descY, w: 1.2, h: 0.5, fontSize: 9, fontFace: BF, color: C.dark, align: \"center\", valign: \"top\", margin: 0 });\n  });\n\n  // Why smallpox was uniquely suited\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 3.85, w: 9.0, h: 1.1, fill: { color: C.white }, shadow: shd() });\n  s.addText(\"Why smallpox was uniquely suited for eradication\", { x: 0.7, y: 3.9, w: 5, h: 0.3, fontSize: 12, fontFace: HF, color: C.teal, bold: true, margin: 0 });\n\n  const reasons = [\n    \"The virus infected only humans — no animal reservoir\",\n    \"Symptoms were visually distinguishable, enabling rapid identification\",\n    \"The vaccine was cheap, stable, and highly effective\",\n  ];\n  reasons.forEach((r, i) => {\n    s.addImage(