const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const fs = require("fs");

const {
  FaSyringe, FaClock, FaCheckCircle, FaMapMarkedAlt,
  FaGlobeAmericas, FaShieldAlt, FaExclamationTriangle,
  FaBullseye, FaArrowRight, FaUser
} = require("react-icons/fa");

// ── Color palette (Teal Trust for public health) ──
const C = {
  navy:    "1B2A4A",
  teal:    "028090",
  seafoam: "00A896",
  mint:    "02C39A",
  coral:   "E85D4A",
  lightBg: "F0F5F7",
  white:   "FFFFFF",
  dark:    "1E293B",
  muted:   "64748B",
  paleGrn: "ECFDF5",
  paleCor: "FEF2F2",
  paleAmb: "FFFBEB",
  green:   "10B981",
  amber:   "F59E0B",
  red:     "EF4444",
  ltGray:  "E2E8F0",
};

const HF = "Georgia";
const BF = "Calibri";

// ── Helpers ──
function renderIcon(Icon, color, size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(Icon, { color, size: String(size) })
  );
}
async function iconPng(Icon, color, size = 256) {
  const svg = renderIcon(Icon, color, size);
  const buf = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + buf.toString("base64");
}
function shd() {
  return { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.1 };
}

// ── Main ──
async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Our World in Data";
  pres.title = "The Power of Vaccination";

  // Pre-render icons
  const ico = {};
  const iconDefs = [
    ["syringe", FaSyringe, "#FFFFFF"],
    ["clock",   FaClock,   "#028090"],
    ["check",   FaCheckCircle, "#10B981"],
    ["map",     FaMapMarkedAlt, "#028090"],
    ["globe",   FaGlobeAmericas, "#028090"],
    ["shield",  FaShieldAlt, "#028090"],
    ["shieldW", FaShieldAlt, "#FFFFFF"],
    ["warn",    FaExclamationTriangle, "#E85D4A"],
    ["bullseye",FaBullseye, "#FFFFFF"],
    ["arrow",   FaArrowRight, "#028090"],
    ["user",    FaUser, "#64748B"],
    ["userTeal",FaUser, "#028090"],
    ["checkW",  FaCheckCircle, "#FFFFFF"],
  ];
  for (const [name, Icon, color] of iconDefs) {
    ico[name] = await iconPng(Icon, color);
  }

  // Heatmap image
  const fig2 = "image/jpeg;base64," + fs.readFileSync("/app/benchmark/assets/figure_2.jpg").toString("base64");

  // ══════════════════════════════════════════════════════
  // SLIDE 1 — TITLE
  // ══════════════════════════════════════════════════════
  let s = pres.addSlide();
  s.background = { color: C.navy };

  s.addShape(pres.shapes.OVAL, { x: 7.2, y: -2.0, w: 5, h: 5, fill: { color: C.teal, transparency: 88 } });
  s.addShape(pres.shapes.OVAL, { x: -1.5, y: 3.0, w: 3, h: 3, fill: { color: C.seafoam, transparency: 92 } });
  s.addShape(pres.shapes.OVAL, { x: 8.5, y: 4.0, w: 2, h: 2, fill: { color: C.mint, transparency: 90 } });

  s.addImage({ data: ico.syringe, x: 0.7, y: 0.45, w: 0.5, h: 0.5 });
  s.addText("VACCINATION", { x: 1.3, y: 0.45, w: 3, h: 0.5, fontSize: 12, fontFace: BF, color: C.seafoam, bold: true, charSpacing: 4, valign: "middle", margin: 0 });

  s.addText("The Power of Vaccination", { x: 0.7, y: 1.2, w: 8.5, h: 1.0, fontSize: 40, fontFace: HF, color: C.white, bold: true, margin: 0 });
  s.addText("From Smallpox Eradication to COVID-19 in Record Time", { x: 0.7, y: 2.3, w: 7, h: 0.6, fontSize: 20, fontFace: BF, color: C.seafoam, margin: 0 });

  s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: 3.2, w: 2.0, h: 0.45, fill: { color: C.teal } });
  s.addText("1796 – 2020", { x: 0.7, y: 3.2, w: 2.0, h: 0.45, fontSize: 15, fontFace: BF, color: C.white, bold: true, align: "center", valign: "middle", margin: 0 });

  s.addText("A data-driven overview of how vaccines have transformed public health\nby eliminating or drastically reducing deadly diseases over two centuries.", { x: 0.7, y: 4.0, w: 6.5, h: 0.8, fontSize: 13, fontFace: BF, color: C.muted, margin: 0 });

  s.addText("Source: Our World in Data — ourworldindata.org/vaccination", { x: 0.7, y: 5.05, w: 6, h: 0.3, fontSize: 10, fontFace: BF, color: C.muted, margin: 0 });

  // ══════════════════════════════════════════════════════
  // SLIDE 2 — VACCINE TIMELINE ACCELERATION
  // ══════════════════════════════════════════════════════
  s = pres.addSlide();
  s.background = { color: C.lightBg };

  s.addImage({ data: ico.clock, x: 0.5, y: 0.3, w: 0.4, h: 0.4 });
  s.addText("From 100 Years to Under 1 Year: Vaccine Development Is Accelerating", { x: 1.0, y: 0.25, w: 8.5, h: 0.55, fontSize: 20, fontFace: HF, color: C.dark, bold: true, margin: 0 });

  // Subtitle
  s.addText("Time from pathogen identification to vaccine licensure", { x: 1.0, y: 0.75, w: 5, h: 0.3, fontSize: 11, fontFace: BF, color: C.muted, margin: 0 });

  // Build horizontal bars with shapes for full control
  const barData = [
    { name: "Typhoid",        years: 105, color: C.teal },
    { name: "Meningitis",     years: 92,  color: C.teal },
    { name: "Polio",          years: 47,  color: C.teal },
    { name: "Ebola",          years: 43,  color: C.teal },
    { name: "Whooping Cough", years: 42,  color: C.teal },
    { name: "Chickenpox",     years: 42,  color: C.teal },
    { name: "Hepatitis B",    years: 16,  color: C.teal },
    { name: "Measles",        years: 10,  color: C.teal },
    { name: "COVID-19",       years: 1,   color: C.coral },
  ];

  const labelX = 0.5;
  const labelW = 1.8;
  const barX = 2.4;
  const maxBarW = 5.0;
  const barStartY = 1.15;
  const barH = 0.32;
  const barGap = 0.12;

  barData.forEach((d, i) => {
    const y = barStartY + i * (barH + barGap);
    const w = Math.max(d.years / 105 * maxBarW, 0.15);

    // Disease label
    s.addText(d.name, { x: labelX, y: y, w: labelW, h: barH, fontSize: 11, fontFace: BF, color: C.dark, align: "right", valign: "middle", margin: 0 });

    // Bar
    s.addShape(pres.shapes.RECTANGLE, { x: barX, y: y, w: w, h: barH, fill: { color: d.color } });

    // Value label
    const label = d.name === "COVID-19" ? "<1 yr" : d.years + " yrs";
    s.addText(label, { x: barX + w + 0.1, y: y, w: 1.2, h: barH, fontSize: 10, fontFace: BF, color: d.color, bold: true, valign: "middle", margin: 0 });
  });

  // COVID-19 callout box
  const cbY = 1.15;
  s.addShape(pres.shapes.RECTANGLE, { x: 7.5, y: cbY, w: 2.2, h: 1.6, fill: { color: C.coral }, shadow: shd() });
  s.addText([
    { text: "COVID-19", options: { bold: true, fontSize: 13, color: C.white, breakLine: true } },
    { text: "<1 year", options: { bold: true, fontSize: 26, color: C.white, breakLine: true } },
    { text: "Pathogen to licensure", options: { fontSize: 10, color: C.white } },
  ], { x: 7.6, y: cbY + 0.1, w: 2.0, h: 1.3, valign: "middle", margin: 0 });

  // Key driver
  s.addShape(pres.shapes.RECTANGLE, { x: 7.5, y: cbY + 1.85, w: 2.2, h: 2.0, fill: { color: C.white }, shadow: shd() });
  s.addText([
    { text: "Key Driver\n", options: { bold: true, fontSize: 11, color: C.teal, breakLine: true } },
    { text: "mRNA technology, genome sequencing, and advanced microscopy have compressed development from over a century to months.", options: { fontSize: 10, color: C.dark } },
  ], { x: 7.65, y: cbY + 1.95, w: 1.9, h: 1.8, valign: "top", margin: 0 });

  s.addText("Source: Our World in Data", { x: 0.5, y: 5.2, w: 4, h: 0.3, fontSize: 9, fontFace: BF, color: C.muted, margin: 0 });

  // ══════════════════════════════════════════════════════
  // SLIDE 3 — US DISEASE ELIMINATION TABLE
  // ══════════════════════════════════════════════════════
  s = pres.addSlide();
  s.background = { color: C.lightBg };

  s.addImage({ data: ico.check, x: 0.5, y: 0.3, w: 0.4, h: 0.4 });
  s.addText("100% Case Reduction Achieved for Diphtheria, Polio, and Smallpox in the US", { x: 1.0, y: 0.25, w: 8.5, h: 0.55, fontSize: 18, fontFace: HF, color: C.dark, bold: true, margin: 0 });

  // Helper for table cells
  const hdr = (t) => ({ text: t, options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 9, fontFace: BF, align: "center", valign: "middle" } });
  const elim = (t, bold = false) => ({ text: t, options: { fill: { color: C.paleGrn }, fontSize: 9, fontFace: BF, align: "center", valign: "middle", bold, color: bold ? C.green : C.dark } });
  const elimD = (t) => ({ text: t, options: { fill: { color: C.paleGrn }, fontSize: 9, fontFace: BF, align: "left", valign: "middle", bold: true } });
  const part = (t, bold = false, col = C.dark) => ({ text: t, options: { fill: { color: C.white }, fontSize: 9, fontFace: BF, align: "center", valign: "middle", bold, color: col } });
  const partD = (t) => ({ text: t, options: { fill: { color: C.white }, fontSize: 9, fontFace: BF, align: "left", valign: "middle", bold: true } });
  const gap = (t) => ({ text: t, options: { fill: { color: C.paleCor }, fontSize: 9, fontFace: BF, align: "center", valign: "middle", bold: true, color: C.coral } });
  const gapD = (t) => ({ text: t, options: { fill: { color: C.paleCor }, fontSize: 9, fontFace: BF, align: "left", valign: "middle", bold: true } });

  const tableRows = [
    [hdr("Disease"), hdr("Pre-Vaccine\nCases/million/yr"), hdr("Post-Vaccine\nCases/million/yr"), hdr("Case\nReduction"), hdr("Death\nReduction")],
    [elimD("Diphtheria"),  elim("158"),  elim("0"),   elim("100%", true), elim("100%", true)],
    [elimD("Smallpox"),    elim("250"),  elim("0"),   elim("100%", true), elim("100%", true)],
    [elimD("Acute Polio"), elim("141"),  elim("0"),   elim("100%", true), elim("100%", true)],
    [elimD("Measles"),     elim("3,044"),elim("0.2"), elim("99.99%"),     elim("100%", true)],
    [elimD("Rubella"),     elim("242"),  elim("0.04"),elim("99.98%"),     elim("100%", true)],
    [partD("Pertussis"),   part("1,534"),part("52"),  part("96.6%"),      part("99.7%")],
    [gapD("Hepatitis A"),  gap("465"),   gap("51"),   gap("89%"),         gap("88.7%")],
    [gapD("Hepatitis B"),  gap("273"),   gap("44"),   gap("83.9%"),       gap("83.6%")],
    [gapD("Pneumococcal"), gap("233"),   gap("139"),  gap("40.5%"),       gap("31.3%")],
  ];

  s.addTable(tableRows, {
    x: 0.5, y: 1.0, w: 9.0,
    colW: [1.8, 1.5, 1.5, 1.3, 1.3],
    border: { pt: 0.5, color: C.ltGray },
    rowH: [0.4, 0.32, 0.32, 0.32, 0.32, 0.32, 0.32, 0.32, 0.32, 0.32],
  });

  // Legend
  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.6, w: 0.25, h: 0.2, fill: { color: C.paleGrn } });
  s.addText("100% elimination (cases and/or deaths)", { x: 0.85, y: 4.58, w: 3, h: 0.25, fontSize: 9, fontFace: BF, color: C.muted, margin: 0 });
  s.addShape(pres.shapes.RECTANGLE, { x: 4.0, y: 4.6, w: 0.25, h: 0.2, fill: { color: C.paleCor } });
  s.addText("Incomplete reduction — gaps remain", { x: 4.35, y: 4.58, w: 3, h: 0.25, fontSize: 9, fontFace: BF, color: C.muted, margin: 0 });

  s.addText("Source: Roush & Murphy (2007), via Our World in Data", { x: 0.5, y: 5.2, w: 5, h: 0.3, fontSize: 9, fontFace: BF, color: C.muted, margin: 0 });

  // ══════════════════════════════════════════════════════
  // SLIDE 4 — MEASLES HEATMAP STATES
  // ══════════════════════════════════════════════════════
  s = pres.addSlide();
  s.background = { color: C.lightBg };

  s.addImage({ data: ico.map, x: 0.5, y: 0.3, w: 0.4, h: 0.4 });
  s.addText("Measles Cases Collapsed Across All 50 US States After Vaccine Mandates", { x: 1.0, y: 0.25, w: 8.5, h: 0.55, fontSize: 18, fontFace: HF, color: C.dark, bold: true, margin: 0 });

  // Heatmap image
  const hmH = 3.5;
  const hmW = hmH * (1206 / 970); // preserve aspect ratio ~4.35
  s.addImage({ data: fig2, x: 0.5, y: 1.1, w: hmW, h: hmH });

  // Milestone cards on the right
  const milestones = [
    { year: "1963", desc: "First measles vaccine developed by John Enders", color: C.coral },
    { year: "1971", desc: "MMR (measles-mumps-rubella) vaccine developed by Maurice Hilleman", color: C.amber },
    { year: "1980", desc: "Vaccination became mandatory for children entering kindergarten", color: C.teal },
  ];

  milestones.forEach((m, i) => {
    const my = 1.15 + i * 1.2;
    // Year badge
    s.addShape(pres.shapes.RECTANGLE, { x: 5.3, y: my, w: 0.9, h: 0.4, fill: { color: m.color } });
    s.addText(m.year, { x: 5.3, y: my, w: 0.9, h: 0.4, fontSize: 14, fontFace: BF, color: C.white, bold: true, align: "center", valign: "middle", margin: 0 });
    // Description
    s.addText(m.desc, { x: 6.3, y: my, w: 3.2, h: 0.5, fontSize: 10, fontFace: BF, color: C.dark, valign: "middle", margin: 0 });
  });

  // Key insight
  s.addShape(pres.shapes.RECTANGLE, { x: 5.3, y: 4.55, w: 4.2, h: 0.55, fill: { color: C.white }, shadow: shd() });
  s.addText("Before 1963: 100–1,000+ cases per 100,000. After 1980: near zero — only sporadic outbreaks.", { x: 5.45, y: 4.6, w: 3.9, h: 0.45, fontSize: 10, fontFace: BF, color: C.dark, margin: 0 });

  s.addText("Source: Our World in Data", { x: 0.5, y: 5.2, w: 4, h: 0.3, fontSize: 9, fontFace: BF, color: C.muted, margin: 0 });

  // ══════════════════════════════════════════════════════
  // SLIDE 5 — SMALLPOX ERADICATION STORY
  // ══════════════════════════════════════════════════════
  s = pres.addSlide();
  s.background = { color: C.lightBg };

  s.addImage({ data: ico.globe, x: 0.5, y: 0.3, w: 0.4, h: 0.4 });
  s.addText("Smallpox: The Only Human Disease Eradicated Through Vaccination", { x: 1.0, y: 0.25, w: 8.5, h: 0.55, fontSize: 18, fontFace: HF, color: C.dark, bold: true, margin: 0 });

  // Timeline line
  s.addShape(pres.shapes.LINE, { x: 0.8, y: 2.5, w: 8.4, h: 0, line: { color: C.teal, width: 3 } });

  // Milestone events
  const tlEvents = [
    { year: "1796", desc: "Edward Jenner creates first vaccine using cowpox to trigger immunity", x: 0.8, above: true },
    { year: "1959", desc: "WHO passes resolution to eradicate smallpox", x: 2.9, above: false },
    { year: "1967", desc: "Intensified eradication campaign launched", x: 5.0, above: true },
    { year: "1977", desc: "Last natural case occurs in Somalia", x: 7.1, above: false },
    { year: "1980", desc: "Smallpox declared eradicated worldwide", x: 9.2, above: true },
  ];

  tlEvents.forEach((e) => {
    // Circle marker on line
    s.addShape(pres.shapes.OVAL, { x: e.x - 0.12, y: 2.38, w: 0.24, h: 0.24, fill: { color: C.teal } });
    // Year
    const yearY = e.above ? 1.6 : 2.8;
    s.addText(e.year, { x: e.x - 0.5, y: yearY, w: 1.0, h: 0.35, fontSize: 14, fontFace: BF, color: C.teal, bold: true, align: "center", valign: "middle", margin: 0 });
    // Description
    const descY = e.above ? 1.95 : 3.15;
    s.addText(e.desc, { x: e.x - 0.6, y: descY, w: 1.2, h: 0.5, fontSize: 9, fontFace: BF, color: C.dark, align: "center", valign: "top", margin: 0 });
  });

  // Why smallpox was uniquely suited
  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 3.85, w: 9.0, h: 1.1, fill: { color: C.white }, shadow: shd() });
  s.addText("Why smallpox was uniquely suited for eradication", { x: 0.7, y: 3.9, w: 5, h: 0.3, fontSize: 12, fontFace: HF, color: C.teal, bold: true, margin: 0 });

