const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const fs = require("fs");

const {
  FaSyringe, FaClock, FaCheckCircle, FaMapMarkedAlt,
  FaGlobeAmericas, FaShieldAlt, FaExclamationTriangle,
  FaBullseye, FaArrowRight, FaUser
} = require("react-icons/fa");

// ── Color palette (Teal Trust for public health) ──
const C = {
  navy:    "1B2A4A",
  teal:    "028090",
  seafoam: "00A896",
  mint:    "02C39A",
  coral:   "E85D4A",
  lightBg: "F0F5F7",
  white:   "FFFFFF",
  dark:    "1E293B",
  muted:   "64748B",
  ltMuted: "94A3B8",  // lighter muted for dark backgrounds
  paleGrn: "ECFDF5",
  paleCor: "FEF2F2",
  green:   "10B981",
  amber:   "F59E0B",
  ltGray:  "E2E8F0",
};

const HF = "Georgia";
const BF = "Calibri";

function renderIcon(Icon, color, size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(Icon, { color, size: String(size) })
  );
}
async function iconPng(Icon, color, size = 256) {
  const svg = renderIcon(Icon, color, size);
  const buf = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + buf.toString("base64");
}
function shd() {
  return { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.1 };
}

async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Our World in Data";
  pres.title = "The Power of Vaccination";

  const ico = {};
  const iconDefs = [
    ["syringe", FaSyringe, "#FFFFFF"],
    ["clock",   FaClock,   "#028090"],
    ["check",   FaCheckCircle, "#10B981"],
    ["map",     FaMapMarkedAlt, "#028090"],
    ["globe",   FaGlobeAmericas, "#028090"],
    ["shield",  FaShieldAlt, "#028090"],
    ["shieldW", FaShieldAlt, "#FFFFFF"],
    ["warn",    FaExclamationTriangle, "#E85D4A"],
    ["bullseye",FaBullseye, "#FFFFFF"],
    ["arrow",   FaArrowRight, "#028090"],
    ["checkW",  FaCheckCircle, "#FFFFFF"],
  ];
  for (const [name, Icon, color] of iconDefs) {
    ico[name] = await iconPng(Icon, color);
  }

  const fig2 = "image/jpeg;base64," + fs.readFileSync("/app/benchmark/assets/figure_2.jpg").toString("base64");

  // ══════════════════════════════════════════════════════
  // SLIDE 1 — TITLE
  // ══════════════════════════════════════════════════════
  let s = pres.addSlide();
  s.background = { color: C.navy };

  s.addShape(pres.shapes.OVAL, { x: 7.2, y: -2.0, w: 5, h: 5, fill: { color: C.teal, transparency: 88 } });
  s.addShape(pres.shapes.OVAL, { x: -1.5, y: 3.0, w: 3, h: 3, fill: { color: C.seafoam, transparency: 92 } });
  s.addShape(pres.shapes.OVAL, { x: 8.5, y: 4.0, w: 2, h: 2, fill: { color: C.mint, transparency: 90 } });

  s.addImage({ data: ico.syringe, x: 0.7, y: 0.45, w: 0.5, h: 0.5 });
  s.addText("VACCINATION", { x: 1.3, y: 0.45, w: 3, h: 0.5, fontSize: 12, fontFace: BF, color: C.seafoam, bold: true, charSpacing: 4, valign: "middle", margin: 0 });

  s.addText("The Power of Vaccination", { x: 0.7, y: 1.2, w: 8.5, h: 1.0, fontSize: 40, fontFace: HF, color: C.white, bold: true, margin: 0 });
  s.addText("From Smallpox Eradication to COVID-19 in Record Time", { x: 0.7, y: 2.3, w: 7, h: 0.6, fontSize: 20, fontFace: BF, color: C.seafoam, margin: 0 });

  s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: 3.2, w: 2.0, h: 0.45, fill: { color: C.teal } });
  s.addText("1796 – 2020", { x: 0.7, y: 3.2, w: 2.0, h: 0.45, fontSize: 15, fontFace: BF, color: C.white, bold: true, align: "center", valign: "middle", margin: 0 });

  s.addText("A data-driven overview of how vaccines have transformed public health\nby eliminating or drastically reducing deadly diseases over two centuries.", { x: 0.7, y: 4.0, w: 6.5, h: 0.7, fontSize: 13, fontFace: BF, color: C.ltMuted, margin: 0 });

  s.addText("Source: Our World in Data — ourworldindata.org/vaccination", { x: 0.7, y: 4.95, w: 6, h: 0.25, fontSize: 9, fontFace: BF, color: C.ltMuted, margin: 0 });

  // ══════════════════════════════════════════════════════
  // SLIDE 2 — VACCINE TIMELINE ACCELERATION
  // ══════════════════════════════════════════════════════
