  s.addShape(pres.shapes.RECTANGLE, { x: 4.3, y: legendY, w: 5.2, h: 0.3, fill: { color: C.white }, shadow: shd() });
  s.addText("Vulnerable groups protected:  newborns  •  immunocompromised patients  •  cancer patients on chemotherapy", { x: 4.4, y: legendY + 0.02, w: 5.0, h: 0.25, fontSize: 9, fontFace: BF, color: C.dark, valign: "middle", margin: 0 });

