    s.addText(card.caseRed, { x: cx + 0.15, y: cardY + 0.65, w: cardW - 0.3, h: 0.55, fontSize: 32, fontFace: BF, color: card.color, bold: true, margin: 0 });
    s.addText("case reduction", { x: cx + 0.15, y: cardY + 1.15, w: cardW - 0.3, h: 0.2, fontSize: 10, fontFace: BF, color: C.muted, margin: 0 });

