    const barYc = cardY + 1.5;
    const barMaxW = cardW - 0.3;
    s.addShape(pres.shapes.RECTANGLE, { x: cx + 0.15, y: barYc, w: barMaxW, h: 0.15, fill: { color: C.ltGray } });
    s.addShape(pres.shapes.RECTANGLE, { x: cx + 0.15, y: barYc, w: barMaxW * card.barPct / 100, h: 0.15, fill: { color: card.color } });

