  // SLIDE 8 — TAKEAWAYS AND PRIORITIES
  // ══════════════════════════════════════════════════════
  s = pres.addSlide();
  s.background = { color: C.navy };

  s.addShape(pres.shapes.OVAL, { x: 7.8, y: -1.0, w: 3.5, h: 3.5, fill: { color: C.teal, transparency: 90 } });
  s.addShape(pres.shapes.OVAL, { x: -1.0, y: 3.5, w: 2.5, h: 2.5, fill: { color: C.seafoam, transparency: 92 } });

  s.addImage({ data: ico.bullseye, x: 0.5, y: 0.3, w: 0.4, h: 0.4 });
  s.addText("Key Takeaways", { x: 1.0, y: 0.2, w: 6, h: 0.6, fontSize: 22, fontFace: HF, color: C.white, bold: true, margin: 0 });

  const takeaways = [
    { num: "1", text: "Vaccines achieved 100% elimination of cases and deaths for diphtheria, smallpox, and both forms of polio in the US." },
    { num: "2", text: "Development timelines collapsed from over 100 years (typhoid) to under 1 year (COVID-19), driven by mRNA technology and genomic tools." },
    { num: "3", text: "Measles cases dropped to near zero across all 50 US states following the 1980 kindergarten vaccination mandate." },
    { num: "4", text: "Smallpox remains the only human disease eradicated through vaccination, certified in 1980 after a global campaign." },
    { num: "5", text: "Gaps persist for pneumococcal disease (40.5% case reduction), hepatitis A (89%), and hepatitis B (83.9%)." },
  ];

  takeaways.forEach((t, i) => {
    const ty = 0.9 + i * 0.6;
    s.addShape(pres.shapes.OVAL, { x: 0.6, y: ty, w: 0.35, h: 0.35, fill: { color: C.teal } });
    s.addText(t.num, { x: 0.6, y: ty, w: 0.35, h: 0.35, fontSize: 12, fontFace: BF, color: C.white, bold: true, align: "center", valign: "middle", margin: 0 });
    s.addText(t.text, { x: 1.15, y: ty - 0.02, w: 7.8, h: 0.4, fontSize: 12, fontFace: BF, color: C.white, valign: "middle", margin: 0 });
  });

  const ctaY = 4.1;
  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: ctaY, w: 9.0, h: 0.7, fill: { color: C.teal } });
  s.addText([
    { text: "Call to Action: ", options: { bold: true, fontSize: 14, color: C.white } },
    { text: "Improve access, coverage, and trust in vaccination to close remaining gaps and protect global health systems.", options: { fontSize: 14, color: C.white } },
