cardW - 0.3, h: 0.2, fontSize: 10, fontFace: BF, color: C.muted, margin: 0 });", "+    s.addText("vs. 100% for diphtheria, polio, smallpox", { x: cx + 0.15, y: barYc + 0.48, w: cardW - 0.3, h: 0.2, fontSize: 8, fontFace: BF, color: C.muted, italic: true, margin: 0 });", "   });", " ", "   // Barriers section", "-  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.0, w: 9.0, h: 1.0, fill: { color: C.white }, shadow: shd() });", "-  s.addText("Barriers to full coverage", { x: 0.7, y: 4.05, w: 3, h: 0.3, fontSize: 12, fontFace: HF, color: C.teal, bold: true, margin: 0 });", "+  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 3.85, w: 9.0, h: 0.95, fill: { color: C.white }, shadow: shd() });", "+  s.addText("Barriers to full coverage", { x: 0.7, y: 3.9, w: 3, h: 0.25, fontSize: 12, fontFace: HF, color: C.teal, bold: true, margin: 0 });", " ", "   const barriers = [", "     "Access gaps — not everyone has access to vaccines globally","]}, {"oldStart": 437, "oldLines": 11, "newStart": 403, "newLines": 11, "lines": ["     "Trust challenges — poor scientific understanding can reduce uptake",", "   ];", "   barriers.forEach((b, i) => {", "-    s.addImage({ data: ico.arrow, x: 0.8, y: 4.4 + i * 0.2, w: 0.18, h: 0.18 });", "-    s.addText(b, { x: 1.1, y: 4.38 + i * 0.2, w: 8, h: 0.22, fontSize: 10, fontFace: BF, color: C.dark, valign: "middle", margin: 0 });", "+    s.addImage({ data: ico.arrow, x: 0.8, y: 4.2 + i * 0.18, w: 0.16, h: 0.16 });", "+    s.addText(b, { x: 1.05, y: 4.18 + i * 0.18, w: 8, h: 0.2, fontSize: 10, fontFace: BF, color: C.dark, valign: "middle", margin: 0 });", "   });", " ", "-  s.addText("Source: Our World in Data", { x: 0.5, y: 5.2, w: 4, h: 0.3, fontSize: 9, fontFace: BF, color: C.muted, margin: 0 });", "+  s.addText("Source: Our World in Data", { x: 0.5, y: 5.0, w: 4, h: 0.25, fontSize: 9, fontFace: BF, color: C.muted, margin: 0 });", " ", "   // ══════════════════════════════════════════════════════", "   // SLIDE 8 — TAKEAWAYS AND PRIORITIES"]}, {"ol