hite } },", "     { text: "Improve access, coverage, and trust in vaccination to close remaining gaps and protect global health systems.", options: { fontSize: 14, color: C.white } },", "-  ], { x: 0.7, y: ctaY, w: 8.6, h: 0.75, valign: "middle", margin: 0 });", "+  ], { x: 0.7, y: ctaY, w: 8.6, h: 0.7, valign: "middle", margin: 0 });", " ", "-  s.addText("Source: Our World in Data — ourworldindata.org/vaccination", { x: 0.5, y: 5.2, w: 6, h: 0.3, fontSize: 9, fontFace: BF, color: C.muted, margin: 0 });", "+  s.addText("Source: Our World in Data — ourworldindata.org/vaccination", { x: 0.5, y: 5.0, w: 6, h: 0.25, fontSize: 9, fontFace: BF, color: C.ltMuted, margin: 0 });", " ", "-  // ── Save ──", "   await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });", "   console.log("Presentation saved to /app/output/final_deck.pptx");", " }"]}], "originalFile": null, "userModified": false}

