// Vertical timeline on the left
const tlX = 1.5;
const tlTop = 1.2;
const tlBot = 3.8;
s.addShape(pres.shapes.LINE, { x: tlX, y: tlTop, w: 0, h: tlBot - tlTop, line: { color: C.teal, width: 3 } });

const tlEvents = [
  { year: "1796", desc: "Edward Jenner creates first vaccine using cowpox to trigger immunity" },
  { year: "1959", desc: "WHO passes resolution to eradicate smallpox" },
  { year: "1967", desc: "Intensified eradication campaign launched" },
  { year: "1977", desc: "Last natural case occurs in Somalia" },
  { year: "1980", desc: "Smallpox declared eradicated worldwide" },
];

tlEvents.forEach((e, i) => {
  const ey = tlTop + i * ((tlBot - tlTop) / 4);
  // Circle marker
  s.addShape(pres.shapes.OVAL, { x: tlX - 0.1, y: ey - 0.1, w: 0.2, h: 0.2, fill: { color: C.teal } });
  // Year badge (to the left of the line)
  s.addText(e.year, { x: 0.5, y: ey - 0.15, w: 0.85, h: 0.3, fontSize: 13, fontFace: BF, color: C.teal, bold: true, align: "right", valign: "middle", margin: 0 });
  // Description (to the right)
  s.addText(e.desc, { x: 1.9, y: ey - 0.15, w: 3.5, h: 0.35, fontSize: 11, fontFace: BF, color: C.dark, valign: "middle", margin: 0 });
});

// Why smallpox was uniquely suited — right side
s.addShape(pres.shapes.RECTANGLE, { x: 5.8, y: 1.2, w: 3.7, h: 2.8, fill: { color: C.white }, shadow: shd() });
s.addText("Why smallpox was uniquely suited for eradication", { x: 5.95, y: 1.3, w: 3.4, h: 0.4, fontSize: 12, fontFace: HF, color: C.teal, bold: true, margin: 0 });

const reasons = [
  "The virus infected only humans — no animal reservoir",
  "Symptoms were visually distinguishable, enabling rapid identification",
  "The vaccine was cheap, stable, and highly effective",
];
reasons.forEach((r, i) => {
  s.addImage({ data: ico.checkW, x: 6.05, y: 1.9 + i * 0.6, w: 0.2, h: 0.2 });
  s.addText(r, { x: 6.35, y: 1.9 + i * 0.6, w: 3.0, h: 0.5, fontSize: 10, fontFace: BF, color: C.dark, valign: "middle", margin: 0 });
});

