function drawGrid(grid, offsetX, slide) {
  grid.forEach((row, ri) => {
    row.forEach((cell, ci) => {
      const cx = offsetX + ci * (circleSize + circleGap);
      const cy = gridOffsetY + ri * (circleSize + circleGap);
      const fillColor = cell === 1 ? C.teal : C.muted;
      slide.addShape(pres.shapes.OVAL, { x: cx, y: cy, w: circleSize, h: circleSize, fill: { color: fillColor } });
    });
  });
}

drawGrid(leftGrid, gridOffsetX_L, s);
drawGrid(rightGrid, 5.85, s);

s.addText("Disease spreads easily\nthrough unvaccinated population", { x: 0.7, y: panelY + 2.0, w: 4.0, h: 0.5, fontSize: 9, fontFace: BF, color: C.coral, align: "center", margin: 0 });
s.addText("Vaccinated individuals shield\nvulnerable community members", { x: 5.3, y: panelY + 2.0, w: 4.0, h: 0.5, fontSize: 9, fontFace: BF, color: C.green, align: "center", margin: 0 });

// Legend row
